
#[derive(Clone)]struct ResetCertificate{proved:bool,status:&'static str,quantum_wires:usize,classical_wires:usize,ops:usize,mr:usize,nodes:usize,caps:usize,unresolved:usize,seconds:f64}
fn reset_projection_certificate(ops:&[Op],node_limit:usize,millis:u64)->ResetCertificate{use OperationType::*;let timer=std::time::Instant::now();let mut qs=std::collections::BTreeSet::new();let mut bs=std::collections::BTreeSet::new();let mut mr=0;for o in ops{if matches!(o.kind,X|CX|CCX|Swap|R|Hmr){qs.insert(o.q_target.0);}if matches!(o.kind,CX|CCX|Swap){qs.insert(o.q_control1.0);}if o.kind==CCX{qs.insert(o.q_control2.0);}if o.c_condition.0!=u64::MAX{bs.insert(o.c_condition.0);}if matches!(o.kind,Hmr|BitStore0|BitStore1|BitInvert){bs.insert(o.c_target.0);}if matches!(o.kind,Hmr|R){mr+=1;}}let qids:std::collections::HashMap<_,_>=qs.iter().enumerate().map(|(i,x)|(*x,i)).collect();let bids:std::collections::HashMap<_,_>=bs.iter().enumerate().map(|(i,x)|(*x,i)).collect();let mut a=GlobalAnf::new(32);let mut q:Vec<_>=(0..qs.len()).map(|_|{let id=a.dag.variable(false);GlobalAnf::constant(id)}).collect();let mut projected=q.clone();let mut b:Vec<_>=(0..bs.len()).map(|_|a.fresh()).collect();let mut base=GlobalAnf::constant(1);let mut stack=Vec::new();let mut status="EXACT_PROOF";for(i,o)in ops.iter().enumerate(){if i%128==0&&(a.dag.nodes.len()>node_limit||a.capped>5000||timer.elapsed().as_millis()>millis as u128){status="UNKNOWN_RESOURCE_LIMIT";break;}if matches!(o.kind,Neg|Z|CZ|CCZ|Register|AppendToRegister|DebugPrint){continue;}if o.kind==PopCondition{if let Some(old)=stack.pop(){base=old;continue;}status="UNKNOWN_UNBALANCED_SCOPE";break;}let c=if o.c_condition.0==u64::MAX{base.clone()}else{a.and(&base,&b[bids[&o.c_condition.0]])};let target=||qids[&o.q_target.0];let ct=||bids[&o.c_target.0];match o.kind{CCX=>{let v=a.and(&q[qids[&o.q_control1.0]],&q[qids[&o.q_control2.0]]);let v=a.and(&v,&c);let t=target();q[t]=a.xor(&q[t],&v);},CX=>{let v=a.and(&q[qids[&o.q_control1.0]],&c);let t=target();q[t]=a.xor(&q[t],&v);},X=>{let t=target();q[t]=a.xor(&q[t],&c);},Swap=>{let t=target();let u=qids[&o.q_control1.0];let v=a.xor(&q[t],&q[u]);let v=a.and(&v,&c);q[t]=a.xor(&q[t],&v);q[u]=a.xor(&q[u],&v);},Hmr|R=>{let t=target();let fresh=a.fresh();let nc=a.not(&c);q[t]=a.and(&q[t],&nc);projected[t]=a.and(&projected[t],&nc);if o.kind==Hmr{let bt=ct();let old=a.and(&b[bt],&nc);let new=a.and(&fresh,&c);b[bt]=a.xor(&old,&new);}},BitStore0=>{let bt=ct();let nc=a.not(&c);b[bt]=a.and(&b[bt],&nc);},BitStore1=>{let bt=ct();let nc=a.not(&c);let old=a.and(&b[bt],&nc);b[bt]=a.xor(&old,&c);},BitInvert=>{let bt=ct();b[bt]=a.xor(&b[bt],&c);},PushCondition=>{stack.push(base);base=c;},_=>unreachable!()}}
 let mut unresolved=0;if status=="EXACT_PROOF"{if !stack.is_empty(){status="UNKNOWN_UNBALANCED_SCOPE";}else{for(x,y)in q.iter().zip(&projected){let p=a.xor(x,y);if p.0.iter().any(|(_,c)|a.dag.find(*c)!=0){unresolved+=1;}}if unresolved!=0{status="UNKNOWN_DIFFERENCE_NOT_PROVED_ZERO";}}}let proved=status=="EXACT_PROOF";ResetCertificate{proved,status,quantum_wires:qs.len(),classical_wires:bs.len(),ops:ops.len(),mr,nodes:a.dag.nodes.len(),caps:a.capped,unresolved,seconds:timer.elapsed().as_secs_f64()}}
#[cfg(test)]mod reset_projection_tests{use super::*;
 fn op(k:OperationType,a:u64,t:u64,bt:u64,c:u64)->Op{Op{kind:k,q_control1:QubitId(a),q_control2:QubitId(u64::MAX),q_target:QubitId(t),c_target:BitId(bt),c_condition:BitId(c),r_target:RegisterId(u64::MAX)}}
 #[test]fn conditional_compute_then_measure_is_reset_projection_for_arbitrary_dirty_target(){let n=u64::MAX;let ops=[op(OperationType::PushCondition,n,n,n,0),op(OperationType::CX,0,1,n,n),op(OperationType::Hmr,n,1,1,n),op(OperationType::PopCondition,n,n,n,n)];let r=reset_projection_certificate(&ops,10000,1000);assert!(r.proved);}
 #[test]fn retained_value_change_is_never_certified(){let n=u64::MAX;let ops=[op(OperationType::PushCondition,n,n,n,0),op(OperationType::CX,0,1,n,n),op(OperationType::PopCondition,n,n,n,n)];assert!(!reset_projection_certificate(&ops,10000,1000).proved);}
 #[test]fn measurement_controlled_data_update_is_never_certified(){let n=u64::MAX;let ops=[op(OperationType::Hmr,n,1,1,n),op(OperationType::X,n,0,n,1)];assert!(!reset_projection_certificate(&ops,10000,1000).proved);}
 #[test]fn node_budget_is_unknown_not_a_certificate(){let n=u64::MAX;let ops=[op(OperationType::CX,0,1,n,n)];let r=reset_projection_certificate(&ops,0,1000);assert!(!r.proved);assert_eq!(r.status,"UNKNOWN_RESOURCE_LIMIT");}
}
